-- PostgreSQL design for Vault IX Arena.
-- UUIDs are generated by the application in this design; install pgcrypto if
-- you want database-side gen_random_uuid() defaults.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TYPE competition_status AS ENUM ('draft','registration','active','completed','archived');
CREATE TYPE match_status AS ENUM ('scheduled','reported','awaiting_confirmation','disputed','approved','cancelled','forfeit');
CREATE TYPE game_mode AS ENUM ('hardpoint','search_and_destroy','control');
CREATE TYPE report_status AS ENUM ('submitted','confirmed','disputed','rejected');
CREATE TYPE stat_source AS ENUM ('manual','screenshot_ocr','authorized_api');
CREATE TYPE verification_status AS ENUM ('pending','verified','rejected');

CREATE TABLE users (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  discord_id VARCHAR(32) UNIQUE NOT NULL,
  display_name TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'player' CHECK (role IN ('player','captain','admin','super_admin')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  disabled_at TIMESTAMPTZ
);

CREATE TABLE teams (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  abbreviation VARCHAR(8) NOT NULL,
  logo_url TEXT,
  active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE players (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID UNIQUE REFERENCES users(id),
  gamertag TEXT NOT NULL,
  activision_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE roster_memberships (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id UUID NOT NULL REFERENCES teams(id),
  player_id UUID NOT NULL REFERENCES players(id),
  role TEXT NOT NULL DEFAULT 'player' CHECK (role IN ('player','captain','substitute')),
  starts_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ends_at TIMESTAMPTZ,
  CHECK (ends_at IS NULL OR ends_at > starts_at)
);
CREATE INDEX roster_team_active_idx ON roster_memberships(team_id) WHERE ends_at IS NULL;
CREATE INDEX roster_player_idx ON roster_memberships(player_id, starts_at);

CREATE TABLE seasons (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  status competition_status NOT NULL DEFAULT 'draft',
  starts_at TIMESTAMPTZ,
  ends_at TIMESTAMPTZ,
  rules JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at)
);

CREATE TABLE tournaments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  season_id UUID REFERENCES seasons(id),
  name TEXT NOT NULL,
  format TEXT NOT NULL CHECK (format IN ('single_elimination','double_elimination','round_robin','custom')),
  status competition_status NOT NULL DEFAULT 'draft',
  rules JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE matches (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  season_id UUID REFERENCES seasons(id),
  tournament_id UUID REFERENCES tournaments(id),
  round_name TEXT,
  team_a_id UUID NOT NULL REFERENCES teams(id),
  team_b_id UUID NOT NULL REFERENCES teams(id),
  best_of SMALLINT NOT NULL DEFAULT 5 CHECK (best_of IN (3,5,7)),
  scheduled_at TIMESTAMPTZ,
  status match_status NOT NULL DEFAULT 'scheduled',
  team_a_map_wins SMALLINT NOT NULL DEFAULT 0 CHECK (team_a_map_wins >= 0),
  team_b_map_wins SMALLINT NOT NULL DEFAULT 0 CHECK (team_b_map_wins >= 0),
  winner_team_id UUID REFERENCES teams(id),
  reported_by_user_id UUID REFERENCES users(id),
  approved_by_user_id UUID REFERENCES users(id),
  approved_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (team_a_id <> team_b_id),
  CHECK (team_a_map_wins <= ((best_of / 2) + 1)),
  CHECK (team_b_map_wins <= ((best_of / 2) + 1)),
  CHECK (winner_team_id IS NULL OR winner_team_id IN (team_a_id, team_b_id))
);
CREATE INDEX matches_schedule_idx ON matches(scheduled_at);
CREATE INDEX matches_season_status_idx ON matches(season_id, status);

CREATE TABLE map_results (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  match_id UUID NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  map_number SMALLINT NOT NULL CHECK (map_number BETWEEN 1 AND 7),
  map_name TEXT NOT NULL,
  mode game_mode NOT NULL,
  team_a_score INTEGER,
  team_b_score INTEGER,
  winner_team_id UUID NOT NULL REFERENCES teams(id),
  duration_seconds INTEGER,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(match_id, map_number),
  CHECK (team_a_score IS NULL OR team_a_score >= 0),
  CHECK (team_b_score IS NULL OR team_b_score >= 0),
  CHECK (duration_seconds IS NULL OR duration_seconds >= 0)
);

CREATE TABLE match_reports (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  match_id UUID NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  submitted_by_user_id UUID REFERENCES users(id),
  reporting_team_id UUID NOT NULL REFERENCES teams(id),
  status report_status NOT NULL DEFAULT 'submitted',
  claimed_team_a_wins SMALLINT NOT NULL,
  claimed_team_b_wins SMALLINT NOT NULL,
  evidence_urls JSONB NOT NULL DEFAULT '[]'::jsonb,
  notes TEXT,
  submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(match_id, reporting_team_id),
  CHECK (claimed_team_a_wins >= 0 AND claimed_team_b_wins >= 0)
);

CREATE TABLE player_map_stats (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  map_result_id UUID NOT NULL REFERENCES map_results(id) ON DELETE CASCADE,
  player_id UUID NOT NULL REFERENCES players(id),
  team_id UUID NOT NULL REFERENCES teams(id),
  kills INTEGER CHECK (kills IS NULL OR kills >= 0),
  deaths INTEGER CHECK (deaths IS NULL OR deaths >= 0),
  assists INTEGER CHECK (assists IS NULL OR assists >= 0),
  score INTEGER CHECK (score IS NULL OR score >= 0),
  damage INTEGER CHECK (damage IS NULL OR damage >= 0),
  objective_value JSONB NOT NULL DEFAULT '{}'::jsonb,
  source stat_source NOT NULL DEFAULT 'manual',
  verification verification_status NOT NULL DEFAULT 'pending',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(map_result_id, player_id)
);
CREATE INDEX player_stats_player_idx ON player_map_stats(player_id, verification);
CREATE INDEX player_stats_team_idx ON player_map_stats(team_id, verification);

CREATE TABLE stat_imports (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  match_id UUID REFERENCES matches(id),
  provider TEXT NOT NULL,
  external_reference TEXT,
  status TEXT NOT NULL CHECK (status IN ('queued','processing','succeeded','failed','needs_review')),
  payload JSONB,
  error_message TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  completed_at TIMESTAMPTZ
);

CREATE TABLE standings_snapshots (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  season_id UUID NOT NULL REFERENCES seasons(id),
  team_id UUID NOT NULL REFERENCES teams(id),
  captured_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  played INTEGER NOT NULL DEFAULT 0,
  wins INTEGER NOT NULL DEFAULT 0,
  losses INTEGER NOT NULL DEFAULT 0,
  map_wins INTEGER NOT NULL DEFAULT 0,
  map_losses INTEGER NOT NULL DEFAULT 0,
  points INTEGER NOT NULL DEFAULT 0,
  UNIQUE(season_id, team_id, captured_at)
);

CREATE TABLE match_audit_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  match_id UUID NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  actor_user_id UUID REFERENCES users(id),
  action TEXT NOT NULL,
  reason TEXT,
  before_state JSONB,
  after_state JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX audit_match_idx ON match_audit_logs(match_id, created_at DESC);

CREATE TABLE notifications (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  recipient_user_id UUID REFERENCES users(id),
  match_id UUID REFERENCES matches(id),
  channel TEXT NOT NULL,
  event_type TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued',
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  sent_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
